export type ReportRequest = {
    /**
     * At most 32 attributes of the request as it ran, such as resolution. In a server report they replace the decision's attributes of the same key before rating.
     */
    attributes?: {
        [key: string]: string | boolean | number;
    };
    /**
     * Id of the customer in your system, for a fallback report. An unknown customer is created and follows the default plan. Ignored in a server report.
     */
    customer_id?: string;
    /**
     * Decision the usage belongs to, such as dec_01jbvagescfn78y0938nkrkayd. Required in a server report and rejected in a fallback report. Reporting a decision again returns its first ledger entry.
     */
    decision_id?: string;
    /**
     * Required. server for the usage of a checked decision named by decision_id, fallback for usage that ran without a decision, such as on the fallback outcome while Preburn was unreachable.
     */
    decision_source?: string;
    /**
     * Feature of your product the usage served, for a fallback report, such as text_to_video. Ignored in a server report.
     */
    feature?: string;
    /**
     * A UUID you generate for a fallback report. Reporting the same key again returns the first ledger entry. Ignored in a server report.
     */
    idempotency_key?: string;
    /**
     * Model the request ran on or one of its aliases, for a fallback report, 1 to 200 characters. Ignored in a server report.
     */
    model?: string;
    /**
     * When the request ran. It picks the prices in effect and, in a fallback report, the customer period. The time of the report when omitted.
     */
    occurred_at?: string;
    /**
     * Provider the request ran on, for a fallback report, 1 to 200 characters. Ignored in a server report.
     */
    provider?: string;
    /**
     * Required. Quantity the request used per meter, a non-negative decimal with at most 6 decimals, such as 6 for output_seconds.
     */
    usage?: {
        [key: string]: string;
    };
};

