export type CreatePolicyData = {
    /**
     * Policy document. The server checks every field and answers 422 policy_invalid with one error per failing field.
     */
    body: {
        /**
         * What the policy decides when it matches.
         */
        action: PolicyAction;
        /**
         * Customer id, such as cust_01jbvagescfn78y0938nkrkayd, for level customer and null otherwise.
         */
        customer_id?: string | null;
        /**
         * soft compares the signals once per check. hard reserves the ceiling estimate and re-checks allowance_remaining and limits atomically.
         */
        enforcement: 'soft' | 'hard';
        /**
         * Feature the policy applies to, matching ^[a-z][a-z0-9_]{0,63}$, or null for every feature.
         */
        feature?: string | null;
        /**
         * Who the policy applies to: every customer, the customers of plan_id, or the customer customer_id.
         */
        level: 'everyone' | 'plan' | 'customer';
        /**
         * Name of the policy, 1 to 120 characters.
         */
        name: string;
        /**
         * Outcome for a request that cannot be priced.
         */
        on_uncosted: 'allow' | 'deny';
        /**
         * Outcome the SDK uses when it cannot reach Preburn, returned in every check response as fallback_outcome.
         */
        on_unreachable: 'allow' | 'deny';
        /**
         * Plan id, such as pln_01jbvagescfn78y0938nkrkayd, for level plan and null otherwise. Customers without a plan follow the default plan.
         */
        plan_id?: string | null;
        /**
         * Only active policies take part in checks. Creating a policy without a status makes it active.
         */
        status?: 'active' | 'disabled' | 'archived';
        /**
         * Conditions on the customer's signals under which the policy matches.
         */
        when: PolicyConditionGroup;
    };
    path?: never;
    query?: never;
    url: '/api/v1/policies';
};

